const BRAND_BY_ID = new Map(Object.entries(BRAND_ICONS));

/** The brand glyph for a catalog entry id, if the brand exists in simple-icons. */

export const brandIconFor = (id: string): BrandIcon | undefined => BRAND_BY_ID.get(id);
